using System;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Controls.Primitives;
using System.Windows.Media;
using Microsoft.Win32;
namespace FrameScout {
 public static class DiagnosticUi {
  static bool installed;
  public static void Install(){if(installed)return;installed=true;EventManager.RegisterClassHandler(typeof(Window),ButtonBase.ClickEvent,new RoutedEventHandler((s,e)=>{var b=e.OriginalSource as ButtonBase;if(b!=null)Diagnostics.Log("ui.button",new {Window=((Window)s).Title,Name=b.Name,Tag=b.Tag as string,Caption=b.Content as string});}),true);EventManager.RegisterClassHandler(typeof(MenuItem),MenuItem.ClickEvent,new RoutedEventHandler((s,e)=>{if(s==e.Source)Diagnostics.Log("ui.menu",new {Caption=((MenuItem)s).Header as string});}),true);EventManager.RegisterClassHandler(typeof(DataGrid),Selector.SelectionChangedEvent,new SelectionChangedEventHandler((s,e)=>{if(s!=e.Source)return;var grid=(DataGrid)s;var video=grid.SelectedItem as VideoItem;var subtitle=grid.SelectedItem as SubtitleFile;var cue=grid.SelectedItem as Cue;var finding=grid.SelectedItem as Finding;Diagnostics.Log("ui.selection",new {Control=grid.Name,Index=grid.SelectedIndex,File=video!=null?video.Path:subtitle!=null?subtitle.Path:null,Cue=cue==null?(int?)null:cue.Number,Frame=finding==null?(int?)null:finding.Frame+1});}),true);}
 }
 public sealed partial class Shell {
  FrameStripPreview frameStrip;DateTime nextPositionLog;
  public static ProcessStartInfo ExplorerRevealInfo(string file){string full=Path.GetFullPath(file);return new ProcessStartInfo{FileName=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Windows),"explorer.exe"),Arguments="/select,"+Util.Q(full),UseShellExecute=true};}
  void RevealVideo(VideoItem item){if(item==null)return;try{if(File.Exists(item.Path))Process.Start(ExplorerRevealInfo(item.Path));else{string directory=Path.GetDirectoryName(item.Path);if(!Directory.Exists(directory))throw new DirectoryNotFoundException("文件及所在文件夹已不存在。");Process.Start(new ProcessStartInfo(directory){UseShellExecute=true});}statusText.Text="已在资源管理器中定位："+item.Path;Diagnostics.Log("video.reveal",new {item.Path});}catch(Exception ex){statusText.Text="定位失败："+ex.Message;Diagnostics.Error("video.reveal_error",ex);}}
  void SetupVideoFeatures(){DiagnosticUi.Install();player.MediaOpened+=(s,e)=>Diagnostics.Log("video.media_opened",new{File=current==null?null:current.Path,position,playing,player.NaturalVideoWidth,player.NaturalVideoHeight});player.MediaEnded+=(s,e)=>Diagnostics.Log("video.media_ended",new{File=current==null?null:current.Path,position});player.MediaFailed+=(s,e)=>Diagnostics.Error("video.media_failed",e.ErrorException);var mode=Get<CheckBox>("DiagnosticMode");mode.IsChecked=saved.DiagnosticMode;mode.Checked+=(s,e)=>{Diagnostics.Enable(true);Diagnostics.RegisterSecret(ApiConfig.Load().Key);Diagnostics.Log("settings.snapshot",ReadSettings());var source=PresentationSource.FromVisual(Window);Diagnostics.Log("ui.diagnostic_enabled",new{Width=Window.ActualWidth,Height=Window.ActualHeight,DpiScale=source==null||source.CompositionTarget==null?1:source.CompositionTarget.TransformToDevice.M11});SaveSettings();statusText.Text=Diagnostics.Enabled?"诊断已开启；请重新检测视频以记录逐帧依据。日志："+Diagnostics.LatestDirectory:"诊断无法开启："+Diagnostics.LastError;};mode.Unchecked+=(s,e)=>{Diagnostics.Enable(false);SaveSettings();statusText.Text="诊断已关闭，已记录的日志保留，可从“诊断日志”查看或导出。";};Click("DiagnosticLogs",(s,e)=>ShowDiagnostics());frameStrip=new FrameStripPreview(Get<Button>("HoverFrames"),()=>{if(current==null||current.Info==null)return null;if(playing)Pause(true);return new FrameStripContext{File=current.Path,Info=current.Info,Result=current.Result,Time=position};},time=>Seek(time,true),message=>statusText.Text=message);timer.Tick+=(s,e)=>{mode.IsEnabled=scanCancel==null&&!subtitlePanel.IsBusy;if(Diagnostics.Enabled&&playing&&DateTime.UtcNow>=nextPositionLog){nextPositionLog=DateTime.UtcNow.AddSeconds(1);Diagnostics.Log("video.position",new {File=current==null?null:current.Path,Seconds=position,Frame=current==null?0:FrameAt(position)+1});}};Window.SizeChanged+=(s,e)=>Diagnostics.Log("window.resize",new {window=Window.Title,Width=Window.ActualWidth,Height=Window.ActualHeight});Window.Loaded+=(s,e)=>{var source=PresentationSource.FromVisual(Window);Diagnostics.Log("ui.loaded",new{Width=Window.ActualWidth,Height=Window.ActualHeight,DpiScale=source==null||source.CompositionTarget==null?1:source.CompositionTarget.TransformToDevice.M11});};}
  void ShowDiagnostics(){var window=FrameWindows.Dialog(Window,"诊断日志与帧号查询",950,710);var root=new Grid{Margin=new Thickness(14)};foreach(var height in new[]{GridLength.Auto,GridLength.Auto,GridLength.Auto,new GridLength(1,GridUnitType.Star)})root.RowDefinitions.Add(new RowDefinition{Height=height});var pathBox=new TextBox{Text=Diagnostics.Root,IsReadOnly=true,Margin=new Thickness(0,0,0,8)};root.Children.Add(pathBox);var tools=new WrapPanel{Margin=new Thickness(0,0,0,9)};var open=new Button{Content="打开日志目录"};open.Click+=(s,e)=>{try{string folder=Diagnostics.Root;Directory.CreateDirectory(folder);Process.Start(new ProcessStartInfo(folder){UseShellExecute=true});}catch(Exception ex){statusText.Text=ex.Message;}};var export=new Button{Content="导出全部诊断包…"};var refresh=new Button{Content="刷新记录"};tools.Children.Add(open);tools.Children.Add(export);tools.Children.Add(refresh);Grid.SetRow(tools,1);root.Children.Add(tools);var selection=new Grid{Margin=new Thickness(0,0,0,9)};selection.ColumnDefinitions.Add(new ColumnDefinition());selection.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});selection.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(80)});selection.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});var videosBox=new ComboBox{MinWidth=190,Margin=new Thickness(0,0,9,0),ToolTip="选择当前或历史会话中的视频检测记录"};var frameLabel=new TextBlock{Text="帧号（从1开始）",VerticalAlignment=VerticalAlignment.Center,Margin=new Thickness(0,0,9,0)};var number=new TextBox{Text=(current==null?1:FrameAt(position)+1).ToString(),Margin=new Thickness(0,0,9,0)};var query=new Button{Content="查看判定依据"};selection.Children.Add(videosBox);Grid.SetColumn(frameLabel,1);selection.Children.Add(frameLabel);Grid.SetColumn(number,2);selection.Children.Add(number);Grid.SetColumn(query,3);selection.Children.Add(query);Grid.SetRow(selection,2);root.Children.Add(selection);var text=new TextBox{IsReadOnly=true,AcceptsReturn=true,TextWrapping=TextWrapping.NoWrap,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Auto,FontFamily=new FontFamily("Consolas"),FontSize=12,Text="诊断模式只记录开启之后的检测。\r\n先开启诊断，再对目标视频重新检测，即可按帧号查询依据。\r\n日志会保留参数、逐帧指标、FFmpeg输出、候选判定、操作与错误，不记录API密钥。"};Grid.SetRow(text,3);root.Children.Add(text);Action populate=()=>{videosBox.Items.Clear();foreach(var record in Diagnostics.Records().OrderByDescending(x=>x.StartedUtc))videosBox.Items.Add(new ComboBoxItem{Content=Path.GetFileName(record.File)+" · "+record.Status+" · "+record.StartedUtc,ToolTip=record.File,Tag=record});if(videosBox.Items.Count>0){var match=videosBox.Items.Cast<ComboBoxItem>().FirstOrDefault(x=>current!=null&&((DiagnosticRecord)x.Tag).File.Equals(current.Path,StringComparison.OrdinalIgnoreCase)&&File.Exists(Path.Combine(((DiagnosticRecord)x.Tag).Directory,"analysis.json")));videosBox.SelectedItem=match??videosBox.Items[0];}pathBox.Text=Diagnostics.Root;};refresh.Click+=(s,e)=>populate();populate();query.Click+=async(s,e)=>{int frame;if(!int.TryParse(number.Text,out frame)||frame<1){text.Text="请填写从1开始的帧号。";return;}var item=videosBox.SelectedItem as ComboBoxItem;string file=item==null?(current==null?null:current.Path):((DiagnosticRecord)item.Tag).File;if(file==null){text.Text="请先开启诊断并重新检测一个视频。";return;}string diagnosticId=item==null?null:((DiagnosticRecord)item.Tag).Id;query.IsEnabled=false;try{text.Text=await Task.Run(()=>Diagnostics.Explain(file,frame,diagnosticId));}catch(Exception ex){text.Text="读取诊断失败："+ex.Message;}finally{query.IsEnabled=true;}};export.Click+=async(s,e)=>{var dialog=new SaveFileDialog{Title="导出诊断日志包",Filter="诊断ZIP|*.zip",FileName="FrameScout-诊断-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")};if(dialog.ShowDialog(window)!=true)return;export.IsEnabled=false;try{await Task.Run(()=>Diagnostics.Export(dialog.FileName));text.Text="诊断包已导出："+dialog.FileName+"\r\n包含本地视频路径和调试数据，可用于排查。";}catch(Exception ex){text.Text="导出失败："+ex.Message;}finally{export.IsEnabled=true;}};window.Content=root;window.Show();}
 }
 public sealed partial class SubtitlePanel {
  FrameStripPreview subFrameStrip;
  void SetupSubtitleFrameStrip(){Get<MediaElement>("SubPlayer").MediaOpened+=(s,e)=>Diagnostics.Log("subtitle.media_opened",new{File=current==null?null:current.VideoPath,playStart,playEnd});Get<MediaElement>("SubPlayer").MediaFailed+=(s,e)=>Diagnostics.Error("subtitle.media_failed",e.ErrorException);subFrameStrip=new FrameStripPreview(Get<Button>("SubHoverFrames"),()=>{if(current==null||string.IsNullOrEmpty(current.VideoPath))return null;Pause();var item=VideoLookup==null?null:VideoLookup(current.VideoPath);return new FrameStripContext{File=current.VideoPath,Info=item==null?null:item.Info,Result=item==null?null:item.Result,Time=subPosition};},async time=>{subPosition=time;playing=false;Get<MediaElement>("SubPlayer").Close();await PreviewAt(time);},message=>Status(message));}
 }
}
